          "stepType": "LinkOutput",
          "name": "Link Output",
          "url": {
            "value": "(function execute() {\n    var item = new sn_sc.CatItem(vaInputs.catalog_item_id);\n\n    if (item && item.getRecordClass() === \"sc_cat_item_guide\")\n        return vaVars.baseUri + vaVars.portalName + '?id=sc_cat_item_guide&sys_id=' + vaInputs.catalog_item_id + '&referrer=va';\n    \n    return vaVars.baseUri + vaVars.portalName + '?id=sc_cat_item&sys_id=' + vaInputs.catalog_item_id + '&referrer=va';\n})()",
            "mode": "script"
          },
          "label": {
            "value": "(function execute() {\n    var item = new sn_sc.CatItem(vaInputs.catalog_item_id);\n    if (item) {\n        var catItemJson = item.read({\n            'name' : ''\n        }, false);\n        return catItemJson.name || '';\n    }\n    return '';\n})()\n",
            "mode": "script"
          },
